Method.Implementation:

	#dim status as %Status
	set status = $$$OK
	$$$TRACE("Inside IHC.ITF.Operation.IhcHieCdrDemogrUpdates OnMessage method..")


	try {	

		$$$TRACE("Hl7 Msg : " _ pRequest.RawContent)	
		$$$TRACE("Log Dir : " _ ..LogDirectory)		
		set objCdrUpdate = ##class(org.ihc.itf.cdr.CdrMmiAddsUpdates).%New(..JavaGateway,..LogDirectory _"/" _$$$JobConfigName _".log", 1)
		$$$TRACE("Object name: " _ objCdrUpdate.%ClassName(1))
		set isUpdate = objCdrUpdate.CdrMmiAddsUpdatesCall(pRequest.RawContent, "1")

		if (isUpdate="1"){
			$$$TRACE(" ********* Cdr Update Successfull!! **********"_isUpdate)
		}else{
			$$$TRACE(" ********* Failed to Update CDR!!! **********"_isUpdate)
			if (isUpdate["No record found"){
				do ##class(IHC.ITF.ITFCOMMON.Utility).SkipMsgError("Out-Cdr-Demogr-Gateway-IHCHIEUPDATES",isUpdate_". New adds are not allowed in CDR. Skipping the record.")
			}
		}
	} catch err {	
	        set sysText = ""
 			if (err.%IsA("%Exception.SystemException")){
	 			set sysText = " SystemException: " _err.AsSystemError()_ "; "	 
 			}

 			if (..CheckObject() '= $$$OK) {
		 		$$$TRACE("**** Object does not exists ****")
		 		// Try to re intialize
		 		set result = ..OnInit()
				if (result '= $$$OK){
					Set status = ##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError("Out-Cdr-Demogr-Gateway-IHCHIEUPDATES",sysText)
					return status
				}
	 		} 			
	}	    

	 $$$TRACE("OnMessage status: " _ status)	
	 return status


    If ( ($IsObject(..objCdrUpdate)) && ($IsObject(..objCdrUpdate)) )
	{
			$$$TRACE("Valid Object: " _ ..objCdrUpdate)
			quit $$$OK
	}
    elseif (' $IsObject(..objCdrUpdate))
    {
	    set ..objCdrUpdate = $$$NULLOREF 
	    quit $$$ERROR("Connection to Gateway is broken. " _ tSC)
    }
    else
    {
	    set ..objCdrUpdate = $$$NULLOREF 
	    quit $$$ERROR("Invalid object: objCdrTuxService")
    }
